#include "test_common.h"
#include "donation_camp_management.h"
static BmsStatus_t camp_count(const BmsDonationCamp_t*c,void*x){(void)c;(*(uint32_t*)x)++;return BMS_STATUS_OK;}
static void test_camp_add_traverse(void){BmsDonationCampContext_t c;BmsDonationCamp_t camp;uint32_t count=0;(void)memset(&camp,0,sizeof camp);camp.campId=1;(void)snprintf(camp.name,sizeof camp,"Chennai Camp");camp.date=(BmsDate_t){2026,8,15};(void)snprintf(camp.time,sizeof camp,"09:00");(void)snprintf(camp.venue,sizeof camp,"Community Hall");(void)snprintf(camp.city,sizeof camp,"Chennai");(void)snprintf(camp.organizer,sizeof camp,"Central Blood Bank");(void)snprintf(camp.contactNumber,sizeof camp,"9876543210");(void)snprintf(camp.email,sizeof camp,"camp@test.com");camp.isActive=true;ASSERT_STATUS(BMS_STATUS_OK,DonationCampManagementInitialize(&c));ASSERT_STATUS(BMS_STATUS_OK,DonationCampManagementAdd(&c,&camp));ASSERT_STATUS(BMS_STATUS_OK,DonationCampManagementTraverse(&c,camp_count,&count));CU_ASSERT_EQUAL(count,1U);DonationCampManagementDeinitialize(&c);}
void RegisterDonationCampTests(void){CU_pSuite s=CU_add_suite("Donation Camp",NULL,NULL);CU_add_test(s,"add and traverse",test_camp_add_traverse);}
